import{c as t,Q as o,j as r,m as d}from"./chunks/framework.CyZn50Me.js";const f=JSON.parse('{"title":"ADR-072 — Surface routes (/moon and /mars) share SurfaceScene.svelte; differences are justified per body or rejected as drift","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-072.md","filePath":"adr/ADR-072.md"}'),a={name:"adr/ADR-072.md"};function s(i,e,n,l,c,h){return o(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="adr-072-—-surface-routes-moon-and-mars-share-surfacescene-svelte-differences-are-justified-per-body-or-rejected-as-drift" tabindex="-1">ADR-072 — Surface routes (<code>/moon</code> and <code>/mars</code>) share <code>SurfaceScene.svelte</code>; differences are justified per body or rejected as drift <a class="header-anchor" href="#adr-072-—-surface-routes-moon-and-mars-share-surfacescene-svelte-differences-are-justified-per-body-or-rejected-as-drift" aria-label="Permalink to &quot;ADR-072 — Surface routes (`/moon` and `/mars`) share `SurfaceScene.svelte`; differences are justified per body or rejected as drift&quot;">​</a></h1><blockquote><p>Status · Accepted Date · 2026-05-30 Closes into · <code>src/lib/surface-scene/SurfaceScene.svelte</code> (new shared component) + <code>src/lib/surface-scene/README.md</code> (implementation contract) Related · ADR-037 (Shared <code>surface-site</code> type, <em>deferred</em> shared <code>&lt;SurfaceMap&gt;</code> component — this ADR is the closing of that deferral), ADR-061 (Surface hotspots are regions), Issue <a href="https://github.com/chipi/orrery/issues/42" target="_blank" rel="noreferrer">#42</a> (closed — partial extraction of pure helpers), Issue <a href="https://github.com/chipi/orrery/issues/283" target="_blank" rel="noreferrer">#283</a> (Slice 2 epic) Triggered by · Drift audit comparing <code>/moon/+page.svelte</code> (2143 LOC) and <code>/mars/+page.svelte</code> (2763 LOC), 2026-05-30. Twenty-two divergences identified that were <em>not</em> justified by the bodies being different — they were drift from Mars being implemented after Moon and the implementer making improvements only on Mars.</p></blockquote><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The original plan (ADR-037, closed RFC-012 OQ-1) was for <code>/moon</code> and <code>/mars</code> to share a <code>&lt;SurfaceMap&gt;</code> component. ADR-037 explicitly deferred the extraction: Mars V1 shipped as a focused clone of Moon&#39;s pattern, with the intention to extract once both routes were known-good.</p><p>Issue <a href="https://github.com/chipi/orrery/issues/42" target="_blank" rel="noreferrer">#42</a> opened to track that extraction. It closed with <strong>partial work</strong>: ~35 pure helpers were extracted into <code>src/lib/surface-map/*</code> (12 modules) and <code>src/lib/three/*</code> (23 modules). The orchestration — onMount Three.js scene assembly, per-frame animation loop, reactive Svelte state, template HUD pieces — stayed inline in both routes. Closed as &quot;good enough for v0.6 ship&quot; with a list of drift risks left for later.</p><p>By 2026-05-30, those drift risks had matured. A focused recon of both routes (Issue #283 Slice 2 design phase) found <strong>eight true body differences</strong> and <strong>twenty-two accidental drifts</strong> — places where Mars had been improved without back-porting to Moon (or vice versa, in three cases). The drifts included:</p><ul><li>UX behaviour (Mars&#39;s drag inertia, smooth zoom lerp, fly-in animation, altitude indicator)</li><li>Visual constants (different label sizes, halo radii, label offsets)</li><li>Code architecture (status-badge as CSS classes vs as a function, hover outline target, orbital ring parenting)</li><li>Latent bugs (Moon&#39;s <code>moon-sites.json</code> has 8 orbiters that the route silently filters out)</li></ul><p>Without a deliberate consolidation, every future surface-route change would have to be made twice — and the drift would keep widening, because Slice 3+ of Issue #283 is going to touch this code heavily (rectangular hotspots, sphere → flat-patch transition, scale-aware markers, traverse polyline, HUD).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Build <code>SurfaceScene.svelte</code> and migrate both routes onto it.</strong> The component owns the shared 90 %; routes become thin shells that pass a planet config and a panel snippet. Drift is resolved on the way in — Mars&#39;s improvements back-port to Moon, Moon&#39;s improvements forward-port to Mars, compromise picks where neither was clearly right.</p><h3 id="true-body-differences-stay-as-surfacesceneconfig-knobs" tabindex="-1">True body differences (stay as <code>SurfaceSceneConfig</code> knobs) <a class="header-anchor" href="#true-body-differences-stay-as-surfacesceneconfig-knobs" aria-label="Permalink to &quot;True body differences (stay as `SurfaceSceneConfig` knobs)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Knob</th><th>Justification</th></tr></thead><tbody><tr><td><code>textureUrl</code></td><td>Different bodies → different surfaces</td></tr><tr><td><code>atmosphere?</code></td><td>Mars has one (CO₂, dust); Moon doesn&#39;t (vacuum)</td></tr><tr><td><code>tidalLockOverlay?</code></td><td>Moon is tidally locked → &quot;near side&quot; is a real concept. Mars isn&#39;t</td></tr><tr><td><code>axialTiltDeg</code></td><td>Mars 25.19°; Moon ~0° (1.5° in reality, effectively zero at this rendering scale). Real obliquity is physical, not arbitrary</td></tr><tr><td><code>landerModelBuilder</code></td><td>Moon has Apollo/Luna/Chang&#39;e/Beresheet/SLIM/Chandrayaan-3 catalogue; Mars has Vikings/Pathfinder/MER/Curiosity/Phoenix/Mars 3/Zhurong/Schiaparelli/Beagle 2. Domain content differs</td></tr><tr><td><code>twoDMode</code></td><td>Mars rotates → equirectangular is honest. Moon is tidally locked → two-disc near/far is the only honest projection (a single equirectangular Moon map would imply rotation relative to Earth)</td></tr><tr><td><code>traverses?</code></td><td>Mars has 4 vendored rover paths (Curiosity, Perseverance, Spirit, Opportunity). Moon has historical EVA paths (Apollo 14/15/16/17) and Lunokhod tracks that should be added in a future slice but aren&#39;t vendored today</td></tr><tr><td><code>registerHotspotBuilders</code></td><td>Already consolidated as per-planet bundles in Slice 2A (<code>registerMoonHotspotBuilders</code> / <code>registerMarsHotspotBuilders</code>)</td></tr></tbody></table><h3 id="drifts-that-get-consolidated" tabindex="-1">Drifts that get consolidated <a class="header-anchor" href="#drifts-that-get-consolidated" aria-label="Permalink to &quot;Drifts that get consolidated&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Drift</th><th>Old Moon</th><th>Old Mars</th><th>Consolidation</th><th>Why</th></tr></thead><tbody><tr><td>Camera near plane</td><td>0.5</td><td>0.05</td><td><strong>0.05</strong></td><td>Mars&#39;s allows closer zoom; required for Tier-2 detail</td></tr><tr><td>Initial <code>camR</code></td><td>80</td><td>90</td><td><strong>85</strong></td><td>Compromise — neither value was special</td></tr><tr><td>Initial <code>camP</code> (pitch)</td><td>π/2</td><td>45°</td><td><strong>45°</strong></td><td>Mars&#39;s angled view is more inviting than Moon&#39;s straight-equator view</td></tr><tr><td>Camera zoom range</td><td>[30.2, 200]</td><td>[30.2, 180]</td><td><strong>[30.2, 200]</strong></td><td>Wider zoom-out preserved from Moon</td></tr><tr><td>Surface light intensity</td><td>0.7</td><td>0.8</td><td><strong>0.8</strong></td><td>Mars&#39;s value is brighter; preserve tint difference (Moon <code>0x666688</code>, Mars <code>0x886655</code>) since tint hints at body palette</td></tr><tr><td>Star field</td><td>default (~150 stars)</td><td><code>STAR_FIELD.planet</code></td><td><strong><code>STAR_FIELD.planet</code></strong></td><td>Deliberate value beats accidental default</td></tr><tr><td>Tier-2 opacity ramp range</td><td><code>camR 50 → 33</code></td><td><code>camR 33 → 30.5</code></td><td><strong><code>camR 33 → 30.5</code></strong></td><td>Mars&#39;s range was the more recent tuning that matches actual Tier-2 patch dimensions</td></tr><tr><td>Marker label offset</td><td>(0, 3.2, 0) straight up</td><td>(2.6, 1.4, 0) side+up</td><td><strong>(2.6, 1.4, 0)</strong></td><td>Mars&#39;s offset (deliberate 2026-05-22 improvement) avoids labels sitting on top of the marker</td></tr><tr><td>Marker label size</td><td>1.6</td><td>1.4</td><td><strong>1.4</strong></td><td>Mars&#39;s tighter sizing reads better without competing with the lander glyph</td></tr><tr><td>Marker halo radius</td><td>1.8</td><td>1.4</td><td><strong>1.4</strong></td><td>Mars&#39;s smaller halo is less intrusive</td></tr><tr><td>Auto-spin pause</td><td>URL deep-link only</td><td>Any selection</td><td><strong>Any selection</strong></td><td>Clicking a marker without the body coming to rest is jarring</td></tr><tr><td>Drag inertia</td><td>none</td><td>0.92/frame decay</td><td><strong>0.92/frame on both</strong></td><td>Inertia makes drag feel natural</td></tr><tr><td>Smooth zoom lerp</td><td>snap</td><td>lerp toward target</td><td><strong>Lerp on both</strong></td><td>Mars&#39;s lerp feels much better than instant snap</td></tr><tr><td>Fly-in animation</td><td>longitude flip only (instant)</td><td>full 3D tween (800 ms ease-out cubic)</td><td><strong>Full fly-in on both</strong></td><td>Mars&#39;s deep-link fly-in is a great UX moment</td></tr><tr><td>Hover outline target</td><td>entire marker group</td><td><code>tier0Group</code> only</td><td><strong><code>tier0Group</code> only</strong></td><td>Outlining the label sprite + halo looks messy</td></tr><tr><td>Altitude indicator</td><td>absent</td><td>shown in km above surface</td><td><strong>Shown on both</strong></td><td>&quot;How zoomed am I&quot; is body-agnostic</td></tr><tr><td>Status badge</td><td>predefined CSS classes (<code>.status-completed/ongoing/planned</code>)</td><td>dynamic <code>statusTone()</code> fn</td><td><strong><code>statusTone()</code> on both</strong></td><td>Function approach is more flexible and centralised</td></tr><tr><td>2D pick tolerance</td><td>22 px</td><td>18 px</td><td><strong>20 px on both</strong></td><td>Compromise; neither value had stated rationale</td></tr><tr><td>Orbital ring opacity</td><td>default (0.35)</td><td>explicit <code>0.35 / 0.18 dimmed</code></td><td><strong>Explicit on both</strong></td><td>Dimmed-orbiter visual cue is useful</td></tr><tr><td>Site <code>kind</code> filtering</td><td>onMount filters out orbiters</td><td>both surface + orbiter</td><td><strong>Both kinds on both</strong></td><td>Moon&#39;s <code>moon-sites.json</code> has 8 orbiters (LRO, Chandrayaan-1, Chang&#39;e 1/2, SMART-1, Luna 10, Clementine, Lunar Prospector) that the route was silently filtering out — latent bug</td></tr><tr><td>Orbital ring log divisor</td><td>50</td><td>100</td><td><strong>Derive from <code>max(altitude_km)</code> at load</strong></td><td>Hardcoded values are drift; data-derived scaling adapts to whichever bodies the route renders</td></tr><tr><td>Orbital parent</td><td>scene</td><td><code>marsAxis</code> (inherits planet tilt)</td><td><strong>scene on both</strong></td><td>Orbital mechanics are inertial — orbits shouldn&#39;t inherit a planet&#39;s tilt. Mars was wrong</td></tr></tbody></table><h3 id="behavioural-changes-shipped-by-this-consolidation" tabindex="-1">Behavioural changes shipped by this consolidation <a class="header-anchor" href="#behavioural-changes-shipped-by-this-consolidation" aria-label="Permalink to &quot;Behavioural changes shipped by this consolidation&quot;">​</a></h3><p>The consolidation lands UX changes that users will notice — flagged here so the migration PR can call them out:</p><ul><li><strong>Moon</strong> gains: drag inertia, smooth zoom lerp, deep-link fly-in animation, altitude indicator HUD, orbiter rendering (8 missions previously hidden), auto-spin pause on any selection, smaller markers/halos, side-offset labels, <code>statusTone()</code> badges.</li><li><strong>Mars</strong> loses (in the sense of &quot;reverts to common&quot;): the marsAxis-parented orbiters (orbits will no longer share the planet tilt).</li><li><strong>Both</strong> gain: data-derived orbital ring scaling, more sensible 2D pick tolerance (20 px compromise).</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong>&quot;Preserve all current behaviour&quot;</strong> — would have meant 25+ config knobs on SurfaceScene to preserve drift. Rejected because (a) the resulting god-component would itself be a maintenance burden, and (b) most &quot;differences&quot; weren&#39;t deliberate — they were drift the implementer would have removed if they&#39;d seen the comparison side-by-side.</li><li><strong>&quot;Stay with two route files; extract just render-path helpers&quot;</strong> — the targeted middle path. Rejected by Marko in favour of the full extraction since drift was deemed the root issue, not duplication itself.</li><li><strong>&quot;Skip extraction; live with the duplication for v0.7&quot;</strong> — rejected. Slice 3+ of #283 (rectangular hotspots, sphere → flat-patch, marker primitive, scale-bar HUD, traverse polyline) would multiply the drift surface.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><code>SurfaceScene.svelte</code> becomes the canonical home for surface-route rendering. New routes in this family (hypothetical: Mercury, Vesta) would consume the same component with a third config.</li><li>New body-vs-body differences require either (a) a config knob justified by physical/domain reality (atmosphere, tidal-lock, axial tilt, projection mode, lander catalogue, traverse data availability) OR (b) a fresh ADR explaining why the difference <em>isn&#39;t</em> drift. Future drift is gated.</li><li>The implementation contract — what&#39;s common, what&#39;s a config knob, how to add either — lives in <code>src/lib/surface-scene/README.md</code> for code-level reference. PRs touching surface routes should reference it.</li><li>Issue #42 (closed) is functionally closed-for-real by this ADR. The &quot;drift risks queued&quot; section of #42 is the work this ADR ships.</li><li>ADR-037&#39;s &quot;deferred shared component&quot; line gets a closure footnote — that deferral is now resolved.</li></ul>',21)])])}const p=t(a,[["render",s]]);export{f as __pageData,p as default};
